<?php
declare(strict_types=1);
namespace MarketForecast\Reports;
use RuntimeException;
final class EmailDeliveryService{public function __construct(private readonly mixed $transport=null){}public function send(array $view,string $recipient):array{if(trim($recipient)==='')throw new RuntimeException('Recipient is required.');$from=getenv('MAIL_FROM')?:'administrator@rayanhost.org';$panel=getenv('PANEL_URL')?:'https://rayanhost.org/AlpacaAIApp/public/reports.php';$subject='گزارش روزانه پیش‌بینی بازار AlpacaAIApp — '.($view['report_date']??'—');$html=(new DailyHtmlRenderer())->render($view);$text=(new DailyTextRenderer())->render($view)."\nپنل کاربری: ".$panel."\n";$headers=['From: AlpacaAIApp <'.$from.'>','Reply-To: '.$from,'Date: '.date(DATE_RFC2822),'Message-ID: <alpacaai-'.bin2hex(random_bytes(12)).'@rayanhost.org>','MIME-Version: 1.0','Content-Type: text/html; charset=UTF-8','Content-Transfer-Encoding: base64'];$encoded=rtrim(chunk_split(base64_encode($html),76,"\r\n"));if($this->transport)return ($this->transport)($recipient,$subject,$html,$text);if(getenv('EMAIL_TRANSPORT')==='mail'){$ok=mail($recipient,'=?UTF-8?B?'.base64_encode($subject).'?=',$encoded,implode("\r\n",$headers),'-f'.escapeshellarg($from));return ['status'=>$ok?'SENT':'FAILED','subject'=>$subject,'panel_url'=>$panel];}return ['status'=>'NOT_SENT','reason'=>'mailer_not_configured','subject'=>$subject,'panel_url'=>$panel];}}
